   179		// read" — `shared`, never the store's `admin`. Admin listing is
   180		// `manage_conversations`, which checks a role first.
   181		const rows = await listConversations({
   182			organizationId,
   183			agentId,
   184			scope: scope === "all" ? "shared" : "user",
   185			userId,
   186		});
