   188		// Platform ("all" scope) rows are ACL-gated: a platform conversation is only
   189		// listed if its channel is in the agent's bound channels AND (for ACL-graphed
   190		// connections) the requester is a member — so a user never sees a channel
   191		// transcript they can't read.
   192		let channelVis: ChannelVisibility | null = null;
   193		if (scope === "all") {
   194			channelVis = await resolveChannelVisibility(getDb(), {
   195				organizationId,
   196				agentId,
   197				userId,
   198			});
   199		}
   200	
   201		for (const row of rows) {
   202			const at = row.lastActivityAt.getTime();
   203			const createdAt = row.createdAt.getTime();
   204			if (row.kind === "owned") {
   205				// Routable id is STORED (`thread_id`), never re-parsed out of the id
   206				// string. The migration trigger also covers writes from an old server
   207				// between the pre-upgrade migration and deployment replacement.
   208				const threadId = row.threadId;
   209				if (!threadId || !isSafeThreadId(threadId) || byKey.has(threadId)) {
   210					continue;
   211				}
