   236					id: row.conversationId,
   237					title: row.title ?? row.conversationId,
   238					createdAt,
   239					updatedAt: at,
   240					// Label from the EXPLICIT stored platform, not by parsing the id — an
   241					// opaque/no-colon platform id (e.g. gchat spaces_A_threads_B) would
   242					// otherwise mislabel as "web".
   243					platform: row.platform,
