   261	      SELECT w.id AS watcher_id, w.name, mx.last_at
   262	      FROM (
   263	        SELECT (regexp_match(conversation_id, '_watcher_([0-9]+)_run_'))[1]::int AS watcher_id,
   264	               max(created_at) AS last_at
