   278					id: key,
   279					title: row.name ?? `Behavior ${row.watcher_id}`,
   280					createdAt: at,
   281					updatedAt: at,
   282					platform: "behavior",
   283					conversationId: key,
   284					behaviorId: row.watcher_id,
