155	async function loadChatBehaviorSubscriptions(
156		sql: DbClient,
157		filters: {
158			behaviorOrganizationId?: string;
159			agentId?: string;
160			connectionId?: string;
161			connectionOrganizationId?: string;
162			connectionSlug?: string;
163			channelId?: string;
164			limit?: number;
165			oldestFirst?: boolean;
166		},
167	): Promise<ChatBehaviorSubscription[]> {
168		const native = filters.channelId
169			? nativeChannelIdFromAny(filters.channelId)
170			: null;
171		const behaviorOrgFilter = filters.behaviorOrganizationId
172			? sql`AND s.organization_id = ${filters.behaviorOrganizationId}`
173			: sql``;
174		const agentFilter = filters.agentId
175			? sql`AND s.agent_id = ${filters.agentId}`
176			: sql``;
177		const connectionIdFilter = filters.connectionId
178			? sql`AND s.connection_id = ${filters.connectionId}::bigint`
179			: sql``;
180		const connectionOrgFilter = filters.connectionOrganizationId
181			? sql`AND s.connection_organization_id = ${filters.connectionOrganizationId}`
182			: sql``;
183		const connectionSlugFilter = filters.connectionSlug
184			? sql`AND s.connection_slug = ${filters.connectionSlug}`
185			: sql``;
186		const channelFilter = filters.channelId
187			? sql`AND (
188				s.channel_id = ${filters.channelId}
189				OR s.native_channel_id = ${native}
190			)`
191			: sql``;
192		const limit = filters.limit ? sql`LIMIT ${filters.limit}` : sql``;
193		// Prefer system:chat-link Behaviors over other message.created Behaviors
194		// that share the same channel (digests, recorders). Slash/button routing and
195		// resolveForConnection take LIMIT 1 — without the chat-link preference, a
196		// background Behavior with a newer updated_at steals the interaction.
197		// Tie-break: newest update, then stable behavior_id.
198		const order = filters.oldestFirst
199			? sql`
200				CASE WHEN w.tags @> ARRAY[${CHAT_LINK_TAG}]::text[] THEN 0 ELSE 1 END ASC,
201				s.created_at ASC,
202				s.behavior_id ASC
203			`
204			: sql`
205				CASE WHEN w.tags @> ARRAY[${CHAT_LINK_TAG}]::text[] THEN 0 ELSE 1 END ASC,
206				s.updated_at DESC,
207				s.behavior_id DESC
208			`;
209		const rows = await sql`
210			SELECT s.*
211			FROM behavior_message_subscriptions s
212			JOIN watchers w ON w.id = s.behavior_id
213			WHERE true
214			  ${behaviorOrgFilter}
215			  ${agentFilter}
216			  ${connectionIdFilter}
217			  ${connectionOrgFilter}
218			  ${connectionSlugFilter}
219			  ${channelFilter}
220			ORDER BY ${order}
221			${limit}
222		`;
223		return rows.map(rowToSubscription);
224	}
