   671	  async updateConnection(
   672	    id: string,
   673	    updates: {
   674	      agentId?: string | null;
   675	      config?: PlatformAdapterConfig;
   676	      settings?: ConnectionSettings;
   677	      metadata?: Record<string, any>;
   678			},
   679	  ): Promise<PlatformConnection> {
   680	    const stored = await this.connectionStore.getConnection(id);
   681	    if (!stored) throw new Error(`Connection ${id} not found`);
   682	    const connection = storedToPlatform(stored);
   683	
   684	    // Compute the merged config (skipping sanitized `***...` placeholders),
   685	    // then decide whether a restart is needed.
   686	    const previousConfig = connection.config as Record<string, unknown>;
   687	    let nextConfig: Record<string, unknown> | undefined;
   688	    if (updates.config !== undefined) {
   689	      const merged = { ...previousConfig };
   690	      for (const [key, value] of Object.entries(updates.config)) {
   691	        if (typeof value === "string" && value.startsWith("***")) continue;
   692	        merged[key] = value;
   693	      }
   694	      merged.platform = updates.config.platform;
   695	      nextConfig = merged;
   696	    }
   697	
   698	    // Refuse a merged config the platform rejects (e.g. flipping a Telegram
   699	    // connection to polling mode under LOBU_CLOUD_MODE) BEFORE persisting —
   700	    // otherwise the refused config would be saved `active` and only the next
   701	    // lease tick / hydrate would error it, mirroring addConnection's
   702	    // create-time rejection.
   703	    if (nextConfig !== undefined) {
   704	      const rejection = getPlatformDescriptor(
   705					connection.platform,
   706	      )?.getConfigRejection?.(nextConfig as PlatformAdapterConfig);
   707	      if (rejection) {
   708	        throw new Error(rejection);
   709	      }
   710	    }
   711	
   712	    // previousConfig holds `secret://` refs; nextConfig from the caller
   713	    // holds plaintext values. Resolve previous to plaintext before
   714	    // comparing so an idempotent re-apply with the same bot token
   715	    // doesn't trip a spurious restart.
   716	    const previousResolved =
   717	      nextConfig !== undefined
   718	        ? ((await this.resolveConfigForRuntime(
   719	            id,
   720							previousConfig as PlatformAdapterConfig,
   721	          )) as Record<string, unknown>)
   722	        : previousConfig;
   723	
   724	    const needsRestart =
   725	      nextConfig !== undefined && !configsEqual(nextConfig, previousResolved);
   726	
   727	    if (updates.agentId !== undefined) {
   728	      if (updates.agentId) {
   729	        connection.agentId = updates.agentId;
   730	      } else {
   731	        delete connection.agentId;
   732	      }
   733	    }
   734	    if (nextConfig !== undefined) {
   735	      connection.config = nextConfig as PlatformAdapterConfig;
   736	    }
   737	    if (updates.settings !== undefined) {
   738	      connection.settings = { ...connection.settings, ...updates.settings };
   739	    }
   740	    if (updates.metadata !== undefined) {
   741	      connection.metadata = {
   742	        ...(connection.metadata || {}),
   743	        ...updates.metadata,
   744	      };
   745	    }
   746	    connection.updatedAt = Date.now();
   747	
   748	    // Persist FIRST, then (re)start from the persisted row: the row is the
   749	    // source of truth and its post-write `updated_at` is the memo key every
   750	    // replica converges on. Starting before persisting would stamp the
   751	    // instance with a pre-write version and force a spurious re-hydrate on
   752	    // the next inbound request.
   753	    await this.persistConnection(connection);
   754	    const reread = await this.connectionStore.getConnection(id);
   755	    if (!reread) throw new Error(`Connection ${id} disappeared during update`);
   756	
   757	    if (
   758	      needsRestart &&
   759	      connection.status === "active" &&
   760	      !isAdapterlessPlatform(connection.platform)
   761	    ) {
   762	      if (this.isExclusiveStored(reread)) {
   763	        // Lease-owned: drop any local loop; the claim owner re-hydrates on
   764	        // its next tick via the rowVersion mismatch.
   765	        await this.stopInstance(id);
   766	        this.exclusiveFailures.delete(id);
   767	      } else {
   768	        // Eager restart on the serving pod for immediate config validation;
   769	        // other replicas converge lazily via the rowVersion memo. On failure
   770	        // mark the row errored before rethrowing — the new config is already
   771	        // persisted, and leaving it `active` would misreport a connection
   772	        // that provably cannot start.
   773	        try {
   774	          await this.hydrateFromRow(reread);
   775	        } catch (error) {
   776	          await this.writeConnectionStatus(
   777	            reread,
   778	            "error",
   779							`Startup failed: ${getErrorMessage(error)}`,
   780	          );
   781	          throw error;
   782	        }
   783	      }
   784	    } else {
   785	      const instance = this.instances.get(id);
   786	      if (instance) {
   787	        // Mutate the EXISTING connection object in place: message handlers
   788	        // captured this object at start time, so replacing the reference would
   789	        // hide the change from them until an unrelated restart. And never copy
   790	        // `config` here (no blanket Object.assign): this branch means config
   791	        // didn't meaningfully change, and the warm instance's config holds
   792	        // PLAINTEXT credentials resolved at startup while the store row holds
   793	        // `secret://` refs — clobbering it would make the live adapter read
   794	        // `secret://…` as the bot token. Only agentId / settings / metadata
   795	        // propagate.
   796	        const warm = instance.connection;
   797	        if (updates.agentId !== undefined) {
   798	          if (updates.agentId) {
   799	            warm.agentId = updates.agentId;
   800	          } else {
   801	            delete warm.agentId;
   802	          }
   803	        }
   804	        if (updates.settings !== undefined) {
   805	          warm.settings = { ...warm.settings, ...updates.settings };
   806	        }
   807	        if (updates.metadata !== undefined) {
   808	          warm.metadata = { ...(warm.metadata || {}), ...updates.metadata };
   809	        }
   810	        warm.updatedAt = connection.updatedAt;
   811	        instance.rowVersion = reread.updatedAt;
   812	      }
   813	    }
   814	
   815	    return this.sanitizeConnection(connection);
   816	  }
