   831		/** Secret-aware idempotency check for declarative connection upserts. The
   832		 * stored config contains secret refs, so callers cannot compare it safely
   833		 * themselves without either leaking or spuriously rotating credentials. */
   834		async connectionMatches(
   835			id: string,
   836			config: PlatformAdapterConfig,
   837			settings: ConnectionSettings,
   838			agentId?: string,
   839		): Promise<boolean> {
   840			const stored = await this.connectionStore.getConnection(id);
   841			if (!stored) return false;
   842			const connection = storedToPlatform(stored);
   843			const resolved = await this.resolveConfigForRuntime(id, connection.config);
   844			// Server-stamped keys (e.g. Telegram's auto-generated secretToken) exist
   845			// only on the stored side; ignore them unless the declaration sets one.
   846			const comparable: Record<string, unknown> = { ...resolved };
   847			const stamped =
   848				getPlatformDescriptor(connection.platform)?.serverStampedConfigKeys ?? [];
   849			for (const key of stamped) {
   850				if (!(key in config)) delete comparable[key];
   851			}
   852			// `configsEqual` only reads keys; widen the typed union/interface args to
   853			// the plain record shape it compares over.
   854			return (
   855				configsEqual(comparable, config as Record<string, unknown>) &&
   856				configsEqual(
   857					(connection.settings ?? {}) as Record<string, unknown>,
   858					settings as Record<string, unknown>,
   859				) &&
   860				(connection.agentId ?? undefined) === (agentId ?? undefined)
   861			);
   862		}
