   216	/** Resolve entity slugs to ids; throws when any slug is missing in the org. */
   217	export async function resolveEntitySlugsToIds(
   218		organizationId: string,
   219		slugs: string[],
   220		sql: DbClient = getDb(),
   221	): Promise<number[]> {
   222		const requested = [...new Set(slugs.map((s) => s.trim()).filter(Boolean))];
   223		if (requested.length === 0) return [];
   224		const rows = await sql<{ id: number; slug: string }>`
   225	    SELECT id, slug
   226	    FROM entities
   227	    WHERE organization_id = ${organizationId}
   228	      AND slug = ANY(${pgTextArray(requested)}::text[])
   229	      AND deleted_at IS NULL
   230	  `;
   231		const bySlug = new Map(rows.map((r) => [r.slug, Number(r.id)]));
   232		const missing = requested.filter((slug) => !bySlug.has(slug));
   233		if (missing.length > 0) {
   234			throw new Error(
   235				`entity slug(s) do not exist in this organization: ${missing.join(", ")}`,
   236			);
   237		}
   238		return requested.map((slug) => bySlug.get(slug)!);
   239	}
