    36	    SELECT id FROM feeds
    37	    WHERE connection_id = ${connectionId}::bigint
    38	      AND feed_key = ${feedKey}
    39	      AND kind = 'streaming'
    40	      AND deleted_at IS NULL
    41	    LIMIT 1
    42	  `;
    43		return rows[0] ? Number(rows[0].id) : null;
    44	}
