    68	
    69		const insertWithLock = async (tx: DbClient) => {
    70			await tx.unsafe("SELECT pg_advisory_xact_lock(hashtext($1))", [
    71				`channel-feed:${connectionId}:${channelKey}`,
    72			]);
    73			const again = await findStreamingFeedId(tx, connectionId, channelKey);
    74			if (again !== null) return again;
    75			const inserted = await tx`
    76	      INSERT INTO feeds (
    77	        organization_id, connection_id, feed_key, display_name,
    78	        status, kind, virtual, config
    79	      ) VALUES (
    80	        ${organizationId}, ${connectionId}::bigint, ${channelKey}, ${displayName},
    81	        'active', 'streaming', false, ${tx.json({ store: CHANNEL_FEED_STORE })}::jsonb
    82	      )
    83	      RETURNING id
    84	    `;
    85			return Number(inserted[0].id);
    86		};
    87	
    88		if (opts.sql) return await insertWithLock(sql);
    89		return await sql.begin(insertWithLock);
    90	}
